def load_cases(raw: str, task: str) -> list[dict[str, str]]:
    items = []
    for line in raw.splitlines():
        parts = [chunk.strip() for chunk in line.split("||")]
        expected = 7 if task == "care" else 9
        if len(parts) != expected:
            raise ValueError(f"Expected {expected} fields, found {len(parts)}: {line[:100]}")
        if task == "care":
            scenario, question, cause, act1, act2, focus, source = parts
            items.append(dict(scenario=scenario, task=task, question=question,
                              reason=cause, act1=act1, act2=act2,
                              focus=focus, source=source))
        else:
            scenario, question, cause, check1, check2, act1, act2, focus, source = parts
            items.append(dict(scenario=scenario, task=task, question=question,
                              reason=cause, check1=check1, check2=check2,
                              act1=act1, act2=act2, focus=focus, source=source))
    return items

CARE_CASES = load_cases(CARE_RAW, "care")
