def load_specific(raw: str) -> list[dict]:
    items = []
    for line in raw.splitlines():
        parts = [p.strip() for p in line.split("||")]
        if len(parts) != 9:
            raise ValueError(f"Bad specific case with {len(parts)} parts: {line[:90]}")
        plant, task, question, reason, check1, check2, act1, act2, source = parts
        if task == "care":
            items.append(dict(plant=plant, task=task, scenario="species_"+plant,
                              question=question, reason=reason, act1=check1,
                              act2=check2, source=source, focus=None))
        else:
            items.append(dict(plant=plant, task=task, scenario="species_"+plant,
                              question=question, reason=reason, check1=check1,
                              check2=check2, act1=act1, act2=act2,
                              source=source, focus=None))
    return items

