def render(template: str, plant: dict) -> str:
    return template.format(
        name=plant["name"][0].upper() + plant["name"][1:], gen=plant["gen"], dat=plant["dat"],
        acc=ACC[plant["name"]], ins=INS[plant["name"]]
    )


def generate_answer(case: dict, plant: dict) -> str:
    reason = render(case["reason"], plant)
    act1 = render(case["act1"], plant)
    act2 = render(case["act2"], plant)
    if case.get("focus") == "special":
        extra = SPECIAL_CONTEXT.get(case["scenario"])
        specific = render(extra, plant) if extra else None
    else:
        specific = FOCUS[case["focus"]](plant) if case.get("focus") else None
    if case["task"] == "care":
        condition_lines = [reason]
        if specific:
            condition_lines.append(specific)
        return "Условия:\n" + "\n".join("- " + s for s in condition_lines) + (
            "\n\nРекомендации:\n1. " + act1 + "\n2. " + act2
        )
    checks = [render(case["check1"], plant), render(case["check2"], plant)]
    if specific:
        checks.append(specific)
    return (
        "Возможные причины:\n- " + reason +
        "\n\nЧто проверить:\n" + "\n".join(f"{i}. {s}" for i,s in enumerate(checks,1)) +
        "\n\nЧто делать:\n1. " + act1 + "\n2. " + act2
    )

# Assign generic cases in a balanced way while avoiding anatomical conflicts.
# Each plant receives 7 generic care + 7 generic diagnosis + 1 species-specific each.
assignments = []
counts = defaultdict(int)
for task, cases in (("care", CARE_CASES), ("diagnosis", DIAG_CASES)):
    for p in plants:
        if p["name"] == "пустынный кактус" and task == "diagnosis":
            allowed = CACTUS_CASES
        else:
            allowed = [case for case in cases if p["name"] not in EXCLUDE_FOR.get(case["scenario"], set())]
        # Balance frequency across scenarios; mild seeded randomness prevents fixed patterns.
        scored = sorted(allowed, key=lambda c: (counts[(task,c["scenario"])], RNG.random()))
        selected = scored[:7]
        for case in selected:
            counts[(task,case["scenario"])] += 1
            assignments.append((p,case))

for case in SPECIFIC:
    p = next(plant for plant in plants if plant["name"] == case["plant"])
    assignments.append((p,case))

assert len(assignments) == 400, len(assignments)
# Hold out entire *general scenario families*, balanced on task.
by_task = defaultdict(list)
for p, case in assignments:
    if case["scenario"].startswith("species_"):
        continue
    by_task[case["task"]].append(case["scenario"])

val_families: set[tuple[str,str]] = set()
for task in ("care", "diagnosis"):
    freq = Counter(by_task[task])
    # Find four distinct five-instance families: exact 20 held out per task.
    choices = [key for key, n in freq.items() if n == 5]
    if len(choices) >= 4:
        val_families.update((task, key) for key in sorted(choices)[:4])
    else:
        # deterministic fallback: solve 20 by subset of scenario groups
        options = sorted(freq.items(), key=lambda kv: (kv[1], kv[0]))
        solutions = {0: []}
        for key,n in options:
            for total,chosen in sorted(list(solutions.items()),reverse=True):
                if total+n <= 20 and total+n not in solutions:
                    solutions[total+n] = chosen+[key]
        if 20 not in solutions:
            raise RuntimeError(f"Can't form holdout of 20 examples in {task}: {freq}")
        val_families.update((task, key) for key in solutions[20])

metadata = []
for p, case in assignments:
    task = case["task"]
    split = "validation" if (task,case["scenario"]) in val_families else "train"
    source_ids = list(dict.fromkeys([
        case["source"], SOURCE_BY_PLANT.get(p["name"],
        "H07" if p["group"] == "succulent" else "H01")
    ]))
    metadata.append(dict(
        plant=p["name"], latin=p["latin"], task=task, scenario=case["scenario"],
        split=split, question=render(case["question"],p), answer=generate_answer(case,p),
        source_ids=source_ids,
        source_urls=[SOURCES[id][1] for id in source_ids],
        generation_method="authored_case_bank_with_plant_profiles_v3",
        evidence_level="topical_reference_not_line_by_line_verified",
        expert_review="not_performed",
    ))

# Unique IDs are stable and do not map to v2. Train/validation do not share a scenario family.
metadata.sort(key=lambda x:(x["task"], x["plant"], x["scenario"]))
for i, row in enumerate(metadata, 1):
    row["id"] = f"SFT3-{i:04d}"

train = [row for row in metadata if row["split"] == "train"]
valid = [row for row in metadata if row["split"] == "validation"]
RNG.shuffle(train)
RNG.shuffle(valid)
metadata = train + valid
assert len(train) == 360 and len(valid) == 40, (len(train),len(valid))
assert Counter(x["task"] for x in train) == Counter({"care":180,"diagnosis":180})
assert Counter(x["task"] for x in valid) == Counter({"care":20,"diagnosis":20})


def write_jsonl(filename: str, rows: list[dict]) -> None:
    with (DATA/filename).open("w",encoding="utf8",newline="\n") as file:
        for row in rows:
            file.write(json.dumps(row,ensure_ascii=False)+"\n")

write_jsonl("train.jsonl", [dict(messages=[
    dict(role="user",content=x["question"]),
    dict(role="assistant",content=x["answer"])
]) for x in train])
write_jsonl("validation.jsonl", [dict(messages=[
    dict(role="user",content=x["question"]),
    dict(role="assistant",content=x["answer"])
]) for x in valid])
write_jsonl("sft_metadata.jsonl", metadata)
with (DATA/"sft_provenance.csv").open("w",encoding="utf8",newline="") as file:
    fields = ["id","split","task","plant","scenario","source_ids","source_urls","generation_method","evidence_level","expert_review"]
    writer = csv.DictWriter(file,fieldnames=fields)
    writer.writeheader()
    for row in metadata:
        writer.writerow({key:(";".join(row[key]) if isinstance(row.get(key),list) else row.get(key,"")) for key in fields})
with (DATA/"sources.csv").open("w",encoding="utf-8",newline="") as file:
    writer=csv.writer(file)
    writer.writerow(["source_id","source_name","url","support_scope"])
    for key,(title,url) in SOURCES.items():
        writer.writerow([key,title,url,"topical guidance; each synthetic claim not individually verified"])

# Keep baseline evaluation questions byte-for-byte unchanged.
original_eval = ROOT / "data" / "eval_questions.jsonl"
if not original_eval.exists():
    raise FileNotFoundError(original_eval)

# Fully automated audit; semantic/botanical validity cannot be inferred from these metrics.
raw_question=[m["question"] for m in metadata]
raw_answer=[m["answer"] for m in metadata]
normalize=lambda s: re.sub(r"\s+"," ",s.strip().casefold())
eval_data=[json.loads(x) for x in original_eval.read_text(encoding="utf8").splitlines() if x.strip()]
assert len(set(map(normalize,raw_question))) == 400
assert len(set(map(normalize,raw_answer))) == 400
assert not set(map(normalize,raw_question)) & {normalize(x["question"]) for x in eval_data}
assert not { (x["task"],x["scenario"]) for x in train } & { (x["task"],x["scenario"]) for x in valid }
for m in metadata:
    assert all(m["answer"].count(h) == 1 for h in (
        ["Условия:","Рекомендации:"] if m["task"]=="care" else
        ["Возможные причины:","Что проверить:","Что делать:"]
    ))
    assert len(m["answer"]) > 180
    assert len(m["answer"]) < 2500
    assert len(m["question"]) > 30
    assert all(sid in SOURCES for sid in m["source_ids"])

